{
  "reply": "I have updated the primary gloss, short gloss, notes, and the Russian translations of the examples to use «бездонный», making it the main everyday equivalent while keeping «абиссальный» in the scientific sense.",
  "followUps": [
    "One more example",
    "How do I remember it?"
  ],
  "proposal": {
    "summary": "Changes the main Russian terms from «абиссальный» to «бездонный» in the glosses, notes, and examples.",
    "ops": [
      {
        "op": "set",
        "target": "lexeme",
        "field": "shortGloss",
        "value": "бездонный; глубоководный"
      },
      {
        "op": "set",
        "target": "lexeme",
        "field": "primaryGloss",
        "value": "бездонный"
      },
      {
        "op": "set",
        "target": "lexeme",
        "field": "notes",
        "value": [
          "Используется как в научном значении («абиссальный»), так и в переносном или описательном смысле как «бездонный»."
        ]
      },
      {
        "op": "set",
        "target": "sense:lgksiv0a4adcaar",
        "field": "glosses",
        "value": [
          {
            "lang": "ru",
            "terms": [
              "бездонный",
              "глубоководный"
            ]
          }
        ]
      },
      {
        "op": "set",
        "target": "example:pvs056rz7zyuix1",
        "field": "translation",
        "value": "Подводная лодка исследовала бездонные равнины Тихого океана."
      },
      {
        "op": "set",
        "target": "example:pvs056rz7zyuix1",
        "field": "matchedTranslationForm",
        "value": "бездонные"
      }
    ]
  }
}
